test('variant window preparations preserve declarations and NULL operand errors',async t=>{
 const connection=await start(t)
 const actual=await observe(connection,{verifyVersion:false,profilePlan:windowDeclarationProfiles,variantPlan:['api-default','named-one'],execute:false})
 await mkdir('artifacts/prepared-rpc-metadata',{recursive:true})
 await writeFile('artifacts/prepared-rpc-metadata/window-runtime.json',JSON.stringify({expected:windowReference,actual},null,2)+'\n')
 assert.equal(actual.length-2,windowReference.length)
 for(let i=0;i<windowReference.length;i++){
  const expected=windowReference[i],record=actual[i+2],name=expected.name+' '+expected.variant
  assert.deepEqual(record.preparation,expected.preparation,name)
  assert.deepEqual(record.unpreparation,expected.unpreparation,name+' unprepare')
  assert.deepEqual(record.executions,[],name+' no execution')
  assert.deepEqual(record.afterPreparation.result.sets,expected.afterPreparation.result.sets,name+' nonexecution')
  assert.deepEqual(record.afterExecution.result.sets,expected.afterExecution.result.sets,name+' final state')
 }
})

