test('prepared variant provenance distinguishes hidden and projected ORDER keys',async t=>{
 const connection=await start(t)
 const actual=await observe(connection,{verifyVersion:false,profilePlan:orderPropertyProfiles,variantPlan:['api-default','named-one'],execute:false})
 await mkdir('artifacts/prepared-rpc-metadata',{recursive:true})
 await writeFile('artifacts/prepared-rpc-metadata/order-properties-runtime.json',JSON.stringify({expected:orderPropertyReference,actual},null,2)+'\n')
 assert.equal(actual.length-2,orderPropertyReference.length)
 for(let i=0;i<orderPropertyReference.length;i++){
  const expected=orderPropertyReference[i],record=actual[i+2],name=expected.name+' '+expected.variant
  assert.deepEqual([record.name,record.sql,record.variant],[expected.name,expected.sql,expected.variant],name+' request plan')
  assert.deepEqual(record.preparation,expected.preparation,name)
  assert.deepEqual(record.unpreparation,expected.unpreparation,name+' unprepare')
  assert.deepEqual(record.executions,[],name+' no execution')
  assert.deepEqual(record.afterPreparation.result.sets,expected.afterPreparation.result.sets,name+' nonexecution')
  assert.deepEqual(record.afterExecution.result.sets,expected.afterExecution.result.sets,name+' final state')
 }
})
